const modal=document.getElementById('game-modal'),canvas=document.getElementById('game-canvas'),ctx=canvas.getContext('2d'),scoreEl=document.getElementById('game-score'),titleEl=document.getElementById('modal-title'),instructionsEl=document.getElementById('game-instructions'),statusEl=document.getElementById('game-status');
let gameType='',running=false,started=false,score=0,last=0,frame=0,raf;const keys={};
const colors={ink:'#11143a',cream:'#fff6dc',yellow:'#ffcf33',pink:'#f45b83',cyan:'#37d9d0',orange:'#ff885c',green:'#67be64',red:'#d83c5a'};
const weapons={pistol:{name:'PISTOL',damage:18,cooldown:22,color:colors.yellow,icon:'●'},shotgun:{name:'SHOTGUN',damage:42,cooldown:42,color:colors.orange,icon:'◆'},blaster:{name:'BLASTER',damage:10,cooldown:8,color:colors.cyan,icon:'✦'}};
function text(t,x,y,size=14,color=colors.cream,align='left'){ctx.fillStyle=color;ctx.font=`${size}px "Press Start 2P", monospace`;ctx.textAlign=align;ctx.fillText(t,x,y)}function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(x,y,w,h)}
function openGame(type){gameType=type;modal.classList.add('open');modal.setAttribute('aria-hidden','false');started=false;running=false;score=0;frame=0;scoreEl.textContent='00000';titleEl.textContent=type==='battle'?'PIXEL ROYALE':type==='runner'?'COIN DASH':'FLAPPY BYTE';instructionsEl.textContent=type==='battle'?'WASD / ARROWS MOVE · SPACE SHOOTS / LOOTS · Q SWITCHES WEAPONS':type==='runner'?'ARROW KEYS SWITCH LANES · SPACE TO JUMP':'SPACE / UP TO FLAP';statusEl.textContent='PRESS SPACE OR TAP TO START';drawIntro()}
function closeGame(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');running=false;cancelAnimationFrame(raf)}function drawIntro(){rect(0,0,800,450,gameType==='battle'?'#6797e7':gameType==='runner'?'#f77e78':'#49b9d2');text(gameType==='battle'?'LOOT. FIGHT. SURVIVE.':gameType==='runner'?'RUN THE BLOCK':'KEEP FLYING',400,190,26,colors.yellow,'center');text('PRESS SPACE TO START',400,250,14,colors.cream,'center');text('ESC TO EXIT',400,410,10,colors.ink,'center')}
function start(){if(started)return;started=true;running=true;statusEl.textContent='GAME ON!';last=performance.now();raf=requestAnimationFrame(loop)}function loop(now){if(!running)return;const dt=Math.min((now-last)/16.67,2);last=now;frame+=dt;update(dt);draw();scoreEl.textContent=String(Math.floor(score)).padStart(5,'0');raf=requestAnimationFrame(loop)}
let p={x:400,y:300,vx:0,vy:0,lane:1,ground:0,obstacles:[],coins:[],birdY:220,flappyNextPipeFrame:110};function resetState(){p={x:400,y:300,vx:0,vy:0,lane:1,ground:0,obstacles:[],coins:[],birdY:220,flappyNextPipeFrame:110};if(gameType==='battle')resetBattle()}
let battle={health:100,maxHealth:100,weapons:['pistol'],active:0,pickups:[],enemies:[],bullets:[],message:'FIND LOOT',messageTime:0,shootTimer:0};
function resetBattle(){battle={health:100,maxHealth:100,weapons:['pistol'],active:0,pickups:[{type:'weapon',weapon:'shotgun',x:180,y:185},{type:'weapon',weapon:'blaster',x:620,y:330},{type:'medkit',x:365,y:155},{type:'medkit',x:680,y:180}],enemies:[{x:110,y:340,health:100,cooldown:0},{x:690,y:350,health:100,cooldown:20},{x:610,y:120,health:100,cooldown:50},{x:220,y:105,health:100,cooldown:80}],bullets:[],message:'FIND LOOT',messageTime:100,shootTimer:0}}
function update(dt){if(gameType==='battle')updateBattle(dt);if(gameType==='runner')updateRunner(dt);if(gameType==='flappy')updateFlappy(dt)}
function updateBattle(dt){const dx=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0),dy=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0);if(dx||dy){const len=Math.hypot(dx,dy)||1;p.x+=dx/len*4*dt;p.y+=dy/len*4*dt;p.faceX=dx;p.faceY=dy}p.x=Math.max(48,Math.min(700,p.x));p.y=Math.max(80,Math.min(390,p.y));if(keys.q&&frame%12<dt){battle.active=(battle.active+1)%battle.weapons.length;keys.q=false;showBattleMessage('EQUIPPED '+weapons[battle.weapons[battle.active]].name)}const weapon=weapons[battle.weapons[battle.active]];battle.shootTimer=Math.max(0,battle.shootTimer-dt);if(keys.Space||keys[' ']){if(!tryPickup()&&battle.shootTimer<=0)shootBattle(weapon)}battle.bullets.forEach(b=>{b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt});battle.bullets=battle.bullets.filter(b=>b.life>0&&b.x>0&&b.x<760&&b.y>55&&b.y<430);battle.enemies.forEach(enemy=>{if(enemy.health<=0)return;const ex=p.x-enemy.x,ey=p.y-enemy.y,dist=Math.hypot(ex,ey);if(dist>34){enemy.x+=ex/dist*.45*dt;enemy.y+=ey/dist*.45*dt}else if(enemy.cooldown<=0){battle.health=Math.max(0,battle.health-8);enemy.cooldown=65;showBattleMessage('-8 HEALTH')}else enemy.cooldown-=dt});battle.bullets.forEach(b=>battle.enemies.forEach(enemy=>{if(enemy.health>0&&Math.hypot(b.x-enemy.x,b.y-enemy.y)<18){enemy.health=Math.max(0,enemy.health-b.damage);b.life=0;score+=b.damage;showBattleMessage(`${b.damage} DAMAGE`);if(enemy.health===0){score+=100;showBattleMessage('ENEMY DOWN')}}}));if(battle.health<=0)endBattle('YOU WERE ELIMINATED');if(battle.enemies.every(e=>e.health<=0))endBattle('VICTORY ROYALE!');score+=.03*dt}
function shootBattle(weapon){battle.shootTimer=weapon.cooldown;let target=null,best=9999;const fx=p.faceX||1,fy=p.faceY||0; battle.enemies.forEach(enemy=>{if(enemy.health<=0)return;const vx=enemy.x-p.x,vy=enemy.y-p.y,d=Math.hypot(vx,vy),dot=(vx*fx+vy*fy)/(d||1);if(d<330&&dot>.35&&d<best){best=d;target=enemy}});if(!target)target=battle.enemies.filter(e=>e.health>0).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(!target)return;const spread=weapon===weapons.shotgun?[-.14,0,.14]:[0];spread.forEach(angle=>{const a=Math.atan2(target.y-p.y,target.x-p.x)+angle;battle.bullets.push({x:p.x,y:p.y,vx:Math.cos(a)*10,vy:Math.sin(a)*10,damage:weapon.damage,life:40})})}
function tryPickup(){const index=battle.pickups.findIndex(item=>Math.hypot(item.x-p.x,item.y-p.y)<38);if(index<0)return false;const loot=battle.pickups[index];battle.pickups.splice(index,1);if(loot.type==='medkit'){battle.health=Math.min(battle.maxHealth,battle.health+35);showBattleMessage('+35 HEALTH');score+=25}else if(!battle.weapons.includes(loot.weapon)){battle.weapons.push(loot.weapon);battle.active=battle.weapons.length-1;showBattleMessage('PICKED UP '+weapons[loot.weapon].name);score+=50}else showBattleMessage('ALREADY HAVE '+weapons[loot.weapon].name);return true}
function showBattleMessage(message){battle.message=message;battle.messageTime=70;statusEl.textContent=message}function endBattle(message){if(!running)return;running=false;statusEl.textContent=message+' — PRESS RESTART';drawBattle();text(message,380,220,24,message==='VICTORY ROYALE!'?colors.yellow:colors.pink,'center');text('PRESS RESTART TO DROP AGAIN',380,260,11,colors.cream,'center')}
function updateRunner(dt){if(frame%55<dt)p.obstacles.push({x:830,lane:Math.floor(Math.random()*3),kind:'obstacle'});if(frame%43<dt)p.coins.push({x:830,lane:Math.floor(Math.random()*3)});p.obstacles.forEach(o=>o.x-=6*dt);p.coins.forEach(c=>c.x-=6*dt);p.obstacles=p.obstacles.filter(o=>o.x>-50);p.coins=p.coins.filter(c=>{if(c.x<175&&c.x>115&&c.lane===p.lane){score+=10;return false}return c.x>-30});if((keys.ArrowLeft||keys.a)&&frame%10<dt)p.lane=Math.max(0,p.lane-1);if((keys.ArrowRight||keys.d)&&frame%10<dt)p.lane=Math.min(2,p.lane+1);if(keys.Space||keys[' '])p.ground=Math.min(1,p.ground+.15*dt);else p.ground=Math.max(0,p.ground-.12*dt);p.obstacles.forEach(o=>{if(o.x<170&&o.x>115&&o.lane===p.lane&&p.ground<.5)endGame()});score+=.08*dt}
function updateFlappy(dt){p.birdY+=(keys.Space||keys.ArrowUp?-.18:.12)*dt;if((keys.Space||keys.ArrowUp)&&frame%8<dt)p.birdY-=2;if(frame%90<dt)p.obstacles.push({x:820,gap:100+Math.random()*170});p.obstacles.forEach(o=>o.x-=4*dt);p.obstacles=p.obstacles.filter(o=>o.x>-60);p.obstacles.forEach(o=>{if(o.x<250&&o.x>190&&(p.birdY<o.gap-55||p.birdY>o.gap+55))endGame()});if(p.birdY<30||p.birdY>420)endGame();score+=.1*dt}
function draw(){if(gameType==='battle')drawBattle();if(gameType==='runner')drawRunner();if(gameType==='flappy')drawFlappy()}
function drawBattle(){rect(0,0,800,450,'#6797e7');rect(0,55,800,395,'#73bf68');rect(0,320,800,130,'#579e59');for(let i=0;i<14;i++)rect((i*73+30)%760,100+(i%3)*55,25,15,colors.green);rect(0,0,800,48,colors.ink);text('DROP ZONE',16,30,12,colors.yellow);text(`ENEMIES ${battle.enemies.filter(e=>e.health>0).length}`,400,30,10,colors.cream,'center');battle.pickups.forEach(item=>{if(item.type==='medkit'){rect(item.x-13,item.y-13,26,26,colors.cream);rect(item.x-4,item.y-10,8,20,colors.red);rect(item.x-10,item.y-4,20,8,colors.red);text('MEDKIT',item.x,item.y+35,7,colors.cream,'center')}else{rect(item.x-15,item.y-9,30,18,weapons[item.weapon].color);rect(item.x-11,item.y-15,22,8,colors.ink);text(weapons[item.weapon].name,item.x,item.y+31,7,colors.cream,'center')}});battle.enemies.forEach(enemy=>{if(enemy.health<=0){text('✖',enemy.x,enemy.y+8,24,colors.ink,'center');return}rect(enemy.x-14,enemy.y-14,28,28,colors.red);rect(enemy.x-10,enemy.y-29,20,14,colors.orange);rect(enemy.x-7,enemy.y-25,4,4,colors.ink);rect(enemy.x+4,enemy.y-25,4,4,colors.ink);rect(enemy.x-20,enemy.y-40,40,5,colors.ink);rect(enemy.x-20,enemy.y-40,40*(enemy.health/100),5,colors.green)});battle.bullets.forEach(b=>rect(b.x-3,b.y-3,6,6,colors.yellow));rect(p.x-16,p.y-16,32,32,colors.pink);rect(p.x-10,p.y-31,20,15,colors.yellow);rect(p.x-8,p.y-27,4,4,colors.ink);rect(p.x+4,p.y-27,4,4,colors.ink);drawBattleHud();if(battle.messageTime>0){battle.messageTime--;text(battle.message,380,75,11,colors.yellow,'center')}}
function drawBattleHud(){rect(12,370,220,67,'rgba(17,20,58,.9)');text('HEALTH',22,390,9,colors.cream);rect(22,398,170,12,colors.ink);rect(22,398,170*(battle.health/battle.maxHealth),12,battle.health>35?colors.green:colors.red);text(`${battle.health} / 100`,202,409,9,colors.cream,'right');text('INVENTORY',250,390,9,colors.cream);battle.weapons.forEach((weapon,i)=>{const selected=i===battle.active;rect(250+i*92,398,82,27,selected?colors.yellow:colors.ink);text(`${i+1} ${weapons[weapon].name}`,291+i*92,416,7,selected?colors.ink:colors.cream,'center')});text('SPACE: SHOOT / PICK UP',780,438,8,colors.cream,'right')}
function drawRunner(){rect(0,0,800,450,'#f77e78');rect(0,190,800,90,'#ffbf67');rect(0,280,800,170,'#31536e');rect(0,390,800,60,colors.ink);for(let x=-20;x<820;x+=75)rect(x,416,35,8,colors.cream);rect(660,100,55,55,colors.yellow);for(let i=0;i<3;i++){const x=220+i*200;rect(x,285,6,105,colors.ink);rect(x-10,275,26,13,colors.yellow);rect(x+20,330,70,9,colors.ink)}p.coins.forEach(c=>{const x=c.x,y=315-c.lane*35;text('★',x,y,22,colors.yellow,'center')});p.obstacles.forEach(o=>{const x=o.x,y=350-o.lane*35;rect(x,y,34,40,colors.orange);rect(x+5,y+5,24,7,colors.ink)});const py=350-p.lane*35-p.ground*75;rect(145,py,27,44,colors.cyan);rect(150,py-19,19,20,colors.yellow);rect(137,py+38,11,8,colors.ink);rect(169,py+38,11,8,colors.ink)}
function drawFlappy(){rect(0,0,800,450,'#49b9d2');for(let i=0;i<3;i++){rect(90+i*270,85+(i%2)*70,55,11,colors.cream);rect(104+i*270,75+(i%2)*70,28,11,colors.cream)}rect(0,420,800,30,colors.green);p.obstacles.forEach(o=>{rect(o.x,0,42,o.gap-55,colors.green);rect(o.x,o.gap+55,42,450-o.gap-55,colors.green);rect(o.x-4,o.gap-62,50,10,colors.ink);rect(o.x-4,o.gap+52,50,10,colors.ink)});rect(224,p.birdY,31,23,colors.yellow);rect(250,p.birdY+7,13,9,colors.pink);rect(229,p.birdY+5,5,5,colors.ink);text(String(Math.floor(score)).padStart(3,'0'),400,70,23,colors.cream,'center')}
function endGame(){if(!running)return;running=false;statusEl.textContent='GAME OVER — PRESS RESTART';text('GAME OVER',400,210,25,colors.pink,'center');text('PRESS RESTART TO TRY AGAIN',400,250,12,colors.cream,'center')}
document.querySelectorAll('.play-button').forEach(b=>b.addEventListener('click',()=>{gameType=b.dataset.game;resetState();openGame(gameType)}));document.getElementById('close-game').addEventListener('click',closeGame);document.getElementById('restart-game').addEventListener('click',()=>{cancelAnimationFrame(raf);resetState();score=0;frame=0;last=0;flappyWasDown=false;started=false;running=false;Object.keys(keys).forEach(key=>keys[key]=false);drawIntro();statusEl.textContent='PRESS SPACE TO START'});document.addEventListener('keydown',e=>{keys[e.key]=true;if(e.key===' '||e.key==='Spacebar'){e.preventDefault();start()}if(e.key>='1'&&e.key<='9'&&gameType==='battle'){const index=Number(e.key)-1;if(index<battle.weapons.length)battle.active=index}if(e.key==='Escape')closeGame()});document.addEventListener('keyup',e=>keys[e.key]=false);canvas.addEventListener('click',start);document.querySelectorAll('.touch-controls button').forEach(btn=>{const k=btn.dataset.key;btn.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true;start()});btn.addEventListener('pointerup',()=>keys[k]=false);btn.addEventListener('pointerleave',()=>keys[k]=false)});

