function aliveTargets(enemy){return [{x:p.x,y:p.y,health:battle.health,isPlayer:true}].concat(battle.enemies.filter(other=>other!==enemy&&other.health>0).map(other=>({...other,isPlayer:false})))}
function nearestTarget(enemy){return aliveTargets(enemy).sort((a,b)=>Math.hypot(a.x-enemy.x,a.y-enemy.y)-Math.hypot(b.x-enemy.x,b.y-enemy.y))[0]}
