function flappyGapSize(){return Math.min(FLAPPY_GROUND_TOP-FLAPPY_MIN_EDGE*2,FLAPPY_BASE_GAP+(wallet&&wallet.flappyBoost||0)*FLAPPY_GAP_PER_LEVEL)}
